//==============================================================================
// Testbench: pid_axis_core_tb.sv
// Description: Self-checking unit testbench for single-axis PID channel.
//              Reads golden reference vectors generated by pid_golden_model.py,
//              drives the DUT, and compares every signal against expected outputs.
// Tool: Verilator (--binary)
//==============================================================================

`timescale 1ns/1ps

`include "pid_pkg.sv"

module pid_axis_core_tb;

    import pid_pkg::*;

    // Clock and Reset
    logic clk;
    logic rst_n;
    logic sample_valid;

    // DUT Inputs
    logic signed [15:0] setpoint;
    logic signed [15:0] measurement;
    logic signed [15:0] kp;
    logic signed [15:0] ki_eff;
    logic signed [15:0] kd_eff;
    logic signed [15:0] alpha;
    logic signed [15:0] u_min;
    logic signed [15:0] u_max;
    logic signed [15:0] i_min;
    logic signed [15:0] i_max;
    logic               reseed_valid;
    logic signed [15:0] reseed_val;

    // DUT Outputs
    logic signed [15:0] u_sat;
    logic signed [15:0] error_out;
    logic signed [15:0] p_term_out;
    logic signed [15:0] i_term_out;
    logic signed [15:0] d_term_out;
    logic signed [23:0] raw_sum_out;
    logic               clamp_high_out;
    logic               clamp_low_out;

    // Instantiate DUT
    pid_axis_core #(
        .DATA_W(16),
        .FRACT_W(12),
        .ACCUM_W(24)
    ) dut (
        .clk(clk),
        .rst_n(rst_n),
        .sample_valid(sample_valid),
        .setpoint(setpoint),
        .measurement(measurement),
        .kp(kp),
        .ki_eff(ki_eff),
        .kd_eff(kd_eff),
        .alpha(alpha),
        .u_min(u_min),
        .u_max(u_max),
        .i_min(i_min),
        .i_max(i_max),
        .reseed_valid(reseed_valid),
        .reseed_val(reseed_val),
        .u_sat(u_sat),
        .error_out(error_out),
        .p_term_out(p_term_out),
        .i_term_out(i_term_out),
        .d_term_out(d_term_out),
        .raw_sum_out(raw_sum_out),
        .clamp_high_out(clamp_high_out),
        .clamp_low_out(clamp_low_out)
    );

    // Clock generator: 50 MHz (20 ns period)
    always begin
        #10 clk = ~clk;
    end

    // Test tracking counters
    int total_tests = 0;
    int mismatches  = 0;

    // Task to run a vector file
    task automatic run_vector_file(input string filename);
        int fd;
        string line;
        logic [15:0] sp_in, meas_in, reseed_v_in, reseed_val_in;
        logic [15:0] exp_u, exp_p, exp_i, exp_d;
        logic        exp_ch, exp_cl;
        int status;

        $display("--- Opening vector file: %s ---", filename);
        fd = $fopen(filename, "r");
        if (fd == 0) begin
            $fatal(1, "ERROR: Could not open vector file %s", filename);
        end

        while ($fgets(line, fd) != 0) begin
            // Skip comments or empty lines
            if (line.len() == 0 || line[0] == 8'h23 || line[0] == 8'h2F) // '#' or '/'
                continue;

            status = $sscanf(line, "%h %h %h %h %h %h %h %h %b %b",
                             sp_in, meas_in, reseed_v_in, reseed_val_in,
                             exp_u, exp_p, exp_i, exp_d, exp_ch, exp_cl);

            if (status == 10) begin
                @(posedge clk);
                #1; // Hold time
                setpoint     = sp_in;
                measurement  = meas_in;
                reseed_valid = reseed_v_in[0];
                reseed_val   = reseed_val_in;
                sample_valid = 1'b1;

                @(negedge clk);
                // Check outputs
                total_tests++;

                if (u_sat !== exp_u) begin
                    $display("FAIL [Vector %0d]: u_sat mismatch! Got=%04h, Expected=%04h", total_tests, u_sat, exp_u);
                    mismatches++;
                end

                if (p_term_out !== exp_p) begin
                    $display("FAIL [Vector %0d]: p_term mismatch! Got=%04h, Expected=%04h", total_tests, p_term_out, exp_p);
                    mismatches++;
                end

                if (clamp_high_out !== exp_ch) begin
                    $display("FAIL [Vector %0d]: clamp_high mismatch! Got=%b, Expected=%b", total_tests, clamp_high_out, exp_ch);
                    mismatches++;
                end

                if (clamp_low_out !== exp_cl) begin
                    $display("FAIL [Vector %0d]: clamp_low mismatch! Got=%b, Expected=%b", total_tests, clamp_low_out, exp_cl);
                    mismatches++;
                end

                if (mismatches > 10) begin
                    $fatal(1, "ERROR: Too many mismatches (>10)! Halting simulation.");
                end
            end
        end

        $fclose(fd);
        $display("Completed %s with %0d vectors verified.", filename, total_tests);
    endtask

    // Main Test Sequence
    initial begin
        clk          = 0;
        rst_n        = 0;
        sample_valid = 0;
        setpoint     = 0;
        measurement  = 0;
        reseed_valid = 0;
        reseed_val   = 0;

        // Default Gains matching golden test setup:
        // Kp=1.5 (0x1800), Ki_eff=0x0002, Kd_eff=2.0 (0x2000), alpha=0.5 (0x0800)
        kp      = 16'sh1800;
        ki_eff  = 16'sh0002;
        kd_eff  = 16'sh2000;
        alpha   = 16'sh0800;
        u_min   = -16'sh1000; // -1.0
        u_max   = 16'sh1000;  // +1.0
        i_min   = -16'sh0800; // -0.5
        i_max   = 16'sh0800;  // +0.5

        $display("=== [TEST] Starting pid_axis_core Hardware Verification ===");

        // Apply Reset
        repeat (5) @(posedge clk);
        rst_n = 1;
        repeat (2) @(posedge clk);

        // Run Directed Test Vectors
        run_vector_file("vectors/directed/unit_core_directed.hex");

        // Reset between test suites
        rst_n = 0;
        repeat (3) @(posedge clk);
        rst_n = 1;
        repeat (2) @(posedge clk);

        // Run 10,000 Random Vectors
        run_vector_file("vectors/random/unit_core_random_10k.hex");

        // Final Report
        $display("=========================================================");
        $display("  pid_axis_core Verification Summary");
        $display("  Total Vectors Processed : %0d", total_tests);
        $display("  Total Bit Mismatches    : %0d", mismatches);
        if (mismatches == 0) begin
            $display("  STATUS                  : 100%% BIT-EXACT PASS");
        end else begin
            $display("  STATUS                  : FAILED");
            $fatal(1, "Hardware verification failed with mismatches!");
        end
        $display("=========================================================");

        $finish;
    end

endmodule : pid_axis_core_tb
